INSERT INTO public.marketing_pages (id, slug, title, content, published)
    VALUES ('5c2f1573-5422-4d9d-a1f4-a97865a56b30', 'privacy', 'Privacy Policy', '{"eyebrow":"Legal","title":["Privacy","Policy"],"description":"How we collect, use, and protect your personal data when you visit our website or engage with TwentyOne06.","image":null,"body_html":"<h2>Introduction</h2><p>TwentyOne06 is committed to protecting your privacy. This Privacy Policy explains how we collect, use, store, share, and protect your personal data when you visit www.twentyone06.com or engage with our services, and outlines your rights under UAE Federal Decree-Law No. 45 of 2021 on the Protection of Personal Data (''UAE PDPL''). If you have any questions, please contact us at info@twentyone06.com.</p>\n<h2>Who We Are</h2><p>The data controller responsible for your personal data is TWENTYONE ZERO SIX PROJECT MANAGEMENT, operating under the trading name TwentyOne06, registered in Dubai, United Arab Emirates.</p>\n<h2>What Personal Data We Collect</h2><p>We collect personal data when you interact with us. This includes information you provide directly - such as your name, email address, phone number, company name, and project details submitted through our contact forms or by email. When you browse our website, we also collect technical data automatically through cookies and analytics tools, including your IP address, browser type, device information, and pages visited. We may also receive information if you interact with our content on Facebook, Instagram, or LinkedIn. We do not collect sensitive personal data - such as health, biometric, financial, religious, or political information - unless specifically required and with your explicit consent.</p>\n<h2>How We Use Your Personal Data</h2><p>We use your personal data to respond to your enquiries and discuss potential projects; to manage and deliver our services to clients; to improve our website using anonymised analytics; and to send marketing communications where you have given your consent. You may withdraw your consent for marketing at any time by contacting us at info@twentyone06.com. We also process data where required to comply with applicable UAE law. We do not use your personal data for automated decision-making or profiling.</p>\n<h2>Who We Share Your Data With</h2><p>TwentyOne06 does not sell, rent, or trade your personal data. We may share it with trusted service providers who support our business operations - such as hosting providers, email platforms, and analytics tools - who are bound to process your data only in accordance with our instructions. We may also share data with professional advisors or with law enforcement and regulatory authorities where required by law. In the event of a business transfer, your data may be transferred to the relevant third party under the same obligations as set out in this policy.</p>\n<h2>How Long We Keep Your Data</h2><p>We retain your personal data only for as long as necessary. Enquiry data is kept for up to two years from your last contact with us. Client project data is kept for up to seven years following project completion, in line with UAE commercial requirements. Data processed on the basis of consent is kept until you withdraw that consent. Website analytics data is retained in anonymised form for up to 24 months. When no longer needed, your data will be securely deleted or anonymised.</p>\n<h2>Your Rights</h2><p>Under the UAE PDPL, you have the right to access, correct, delete, restrict, or object to the processing of your personal data, and to request a portable copy of your data. To exercise any of these rights, please contact us at info@twentyone06.com. We will respond within 30 days of receipt. Where a request is particularly complex, we may extend this by a further 30 days and will notify you accordingly.</p>\n<h2>Cookies</h2><p>Our website uses cookies to improve your browsing experience and analyse traffic. Essential cookies are required for the Website to function. Analytics cookies are used on an anonymised basis. Marketing cookies are only placed with your explicit consent. You can manage your cookie preferences through your browser settings at any time.</p>\n<h2>Data Security</h2><p>TwentyOne06 takes the security of your personal data seriously and implements appropriate technical and organisational measures to protect it against unauthorised access, loss, or disclosure. While we take all reasonable steps to safeguard your data, no electronic transmission or storage is entirely secure. In the event of a data breach, we will notify the UAE Data Office and affected individuals as required by the UAE PDPL.</p>\n<h2>Third-Party Websites</h2><p>Our website may link to third-party websites. We are not responsible for their privacy practices and encourage you to review their policies before sharing any personal data with them.</p>\n<h2>Changes to This Policy</h2><p>We may update this Privacy Policy from time to time. The date of the most recent update is shown at the top of this page. We encourage you to review it periodically.</p>\n<h2>Contact and Complaints</h2><p>For questions about this Privacy Policy or to exercise your data rights, please contact us:</p>","sections":[{"id":"introduction","title":"Introduction","paragraphs":["TwentyOne06 is committed to protecting your privacy. This Privacy Policy explains how we collect, use, store, share, and protect your personal data when you visit www.twentyone06.com or engage with our services, and outlines your rights under UAE Federal Decree-Law No. 45 of 2021 on the Protection of Personal Data (''UAE PDPL''). If you have any questions, please contact us at info@twentyone06.com."]},{"id":"who-we-are","title":"Who We Are","paragraphs":["The data controller responsible for your personal data is TWENTYONE ZERO SIX PROJECT MANAGEMENT, operating under the trading name TwentyOne06, registered in Dubai, United Arab Emirates."],"showAddress":true},{"id":"what-we-collect","title":"What Personal Data We Collect","paragraphs":["We collect personal data when you interact with us. This includes information you provide directly - such as your name, email address, phone number, company name, and project details submitted through our contact forms or by email. When you browse our website, we also collect technical data automatically through cookies and analytics tools, including your IP address, browser type, device information, and pages visited. We may also receive information if you interact with our content on Facebook, Instagram, or LinkedIn. We do not collect sensitive personal data - such as health, biometric, financial, religious, or political information - unless specifically required and with your explicit consent."]},{"id":"how-we-use","title":"How We Use Your Personal Data","paragraphs":["We use your personal data to respond to your enquiries and discuss potential projects; to manage and deliver our services to clients; to improve our website using anonymised analytics; and to send marketing communications where you have given your consent. You may withdraw your consent for marketing at any time by contacting us at info@twentyone06.com. We also process data where required to comply with applicable UAE law. We do not use your personal data for automated decision-making or profiling."]},{"id":"who-we-share","title":"Who We Share Your Data With","paragraphs":["TwentyOne06 does not sell, rent, or trade your personal data. We may share it with trusted service providers who support our business operations - such as hosting providers, email platforms, and analytics tools - who are bound to process your data only in accordance with our instructions. We may also share data with professional advisors or with law enforcement and regulatory authorities where required by law. In the event of a business transfer, your data may be transferred to the relevant third party under the same obligations as set out in this policy."]},{"id":"retention","title":"How Long We Keep Your Data","paragraphs":["We retain your personal data only for as long as necessary. Enquiry data is kept for up to two years from your last contact with us. Client project data is kept for up to seven years following project completion, in line with UAE commercial requirements. Data processed on the basis of consent is kept until you withdraw that consent. Website analytics data is retained in anonymised form for up to 24 months. When no longer needed, your data will be securely deleted or anonymised."]},{"id":"your-rights","title":"Your Rights","paragraphs":["Under the UAE PDPL, you have the right to access, correct, delete, restrict, or object to the processing of your personal data, and to request a portable copy of your data. To exercise any of these rights, please contact us at info@twentyone06.com. We will respond within 30 days of receipt. Where a request is particularly complex, we may extend this by a further 30 days and will notify you accordingly."]},{"id":"cookies","title":"Cookies","paragraphs":["Our website uses cookies to improve your browsing experience and analyse traffic. Essential cookies are required for the Website to function. Analytics cookies are used on an anonymised basis. Marketing cookies are only placed with your explicit consent. You can manage your cookie preferences through your browser settings at any time."]},{"id":"security","title":"Data Security","paragraphs":["TwentyOne06 takes the security of your personal data seriously and implements appropriate technical and organisational measures to protect it against unauthorised access, loss, or disclosure. While we take all reasonable steps to safeguard your data, no electronic transmission or storage is entirely secure. In the event of a data breach, we will notify the UAE Data Office and affected individuals as required by the UAE PDPL."]},{"id":"third-party","title":"Third-Party Websites","paragraphs":["Our website may link to third-party websites. We are not responsible for their privacy practices and encourage you to review their policies before sharing any personal data with them."]},{"id":"changes","title":"Changes to This Policy","paragraphs":["We may update this Privacy Policy from time to time. The date of the most recent update is shown at the top of this page. We encourage you to review it periodically."]},{"id":"contact","title":"Contact and Complaints","paragraphs":["For questions about this Privacy Policy or to exercise your data rights, please contact us:"],"showAddress":true}],"controller":{"name":"TWENTYONE ZERO SIX PROJECT MANAGEMENT (trading as ''TwentyOne06'')","lines":["Al Maktab, Office 304, 23rd Street","Al Barsha First, Al Barsha, Dubai","United Arab Emirates"],"phone":"+971 4 554 8082","phoneHref":"tel:+97145548082","email":"info@twentyone06.com","web":"www.twentyone06.com","webHref":"https://www.twentyone06.com"}}'::jsonb, true);
INSERT INTO public.marketing_pages (id, slug, title, content, published)
    VALUES ('7dee4cc2-0d35-48e8-ae3d-a6a4b37bc09c', 'terms', 'Terms and Conditions', '{"eyebrow":"Legal","title":["Terms and","Conditions"],"description":"The terms that govern your use of the TwentyOne06 website and how we engage with enquiries and services.","image":null,"body_html":"<h2>1. Introduction</h2><p>Welcome to www.twentyone06.com (''Website''), operated by TWENTYONE ZERO SIX PROJECT MANAGEMENT (trading as ''TwentyOne06''), a full-service interior design and branding studio registered in Dubai, United Arab Emirates under Trade License No. 813936, issued by the Department of Economy and Tourism, Dubai. By accessing or using this Website, you agree to be bound by these Terms and Conditions (''Terms''). If you do not agree to these Terms, please do not continue to use this Website. We reserve the right to amend these Terms at any time, and your continued use of the Website following any amendment constitutes your acceptance of the revised Terms.</p>\n<h2>2. Intellectual Property</h2><p>All content published on this Website - including text, project photography, design concepts, graphics, logos, and branding - is the intellectual property of TwentyOne06 or is used with the express permission of the respective rights holders. All such rights are reserved. You may view and print pages from this Website for personal, non-commercial use only, provided that all copyright notices remain intact. Reproduction, distribution, modification, or commercial use of any content without the prior written consent of TwentyOne06 is strictly prohibited.</p>\n<h2>3. Use of This Website</h2><p>You agree to use this Website only for lawful purposes and in a manner that does not infringe the rights of any third party. You must not use this Website to transmit unsolicited commercial communications, introduce malicious software, attempt to gain unauthorised access to any part of the Website or its systems, copy or extract content without permission, or violate any applicable local, national, or international law or regulation.</p>\n<h2>4. Enquiries and Services</h2><p>Information about TwentyOne06''s services on this Website is provided for general information only and does not constitute a binding offer or contract. Submitting an enquiry through our contact form or by email does not create a contractual relationship between you and TwentyOne06. All project engagements are subject to a separate written agreement between TwentyOne06 and the client.</p>\n<h2>5. Disclaimers and Limitation of Liability</h2><p>The content on this Website is provided in good faith and for general information only. TwentyOne06 makes no warranties, express or implied, regarding the accuracy, completeness, or fitness for purpose of any information on this Website. To the fullest extent permitted by applicable UAE law, TWENTYONE ZERO SIX PROJECT MANAGEMENT shall not be liable for any loss or damage - whether direct, indirect, incidental, or consequential - arising from your use of or reliance on this Website or its content, or from your inability to access the Website. We do not warrant that the Website will be uninterrupted, error-free, or free from viruses or other harmful components.</p>\n<h2>6. Third-Party Links</h2><p>This Website may contain links to third-party websites for your convenience. TwentyOne06 has no control over the content of those websites and accepts no responsibility for them or for any loss or damage that may arise from your use of them. The inclusion of any link does not imply endorsement by TwentyOne06.</p>\n<h2>7. Privacy and Data Protection</h2><p>Your use of this Website is governed by our Privacy Policy, which is incorporated into these Terms by reference. Please review our Privacy Policy to understand how we collect, use, and protect your information.</p>\n<h2>8. Severability</h2><p>If any provision of these Terms is found to be invalid, unlawful, or unenforceable, that provision shall be modified or removed to the minimum extent necessary. The remaining provisions shall continue in full force and effect.</p>\n<h2>9. Governing Law</h2><p>These Terms and Conditions shall be governed by and construed in accordance with the laws of the United Arab Emirates, as applied in the Emirate of Dubai. Any disputes shall be subject to the exclusive jurisdiction of the courts of Dubai, UAE.</p>\n<h2>10. Changes to These Terms</h2><p>TwentyOne06 reserves the right to revise these Terms at any time. The date of the most recent revision is shown at the top of this page. Your continued use of the Website following any changes constitutes your acceptance of the revised Terms.</p>\n<h2>11. Contact Us</h2><p>If you have any questions regarding these Terms and Conditions, please contact us:</p>","sections":[{"id":"introduction","title":"1. Introduction","paragraphs":["Welcome to www.twentyone06.com (''Website''), operated by TWENTYONE ZERO SIX PROJECT MANAGEMENT (trading as ''TwentyOne06''), a full-service interior design and branding studio registered in Dubai, United Arab Emirates under Trade License No. 813936, issued by the Department of Economy and Tourism, Dubai. By accessing or using this Website, you agree to be bound by these Terms and Conditions (''Terms''). If you do not agree to these Terms, please do not continue to use this Website. We reserve the right to amend these Terms at any time, and your continued use of the Website following any amendment constitutes your acceptance of the revised Terms."]},{"id":"intellectual-property","title":"2. Intellectual Property","paragraphs":["All content published on this Website - including text, project photography, design concepts, graphics, logos, and branding - is the intellectual property of TwentyOne06 or is used with the express permission of the respective rights holders. All such rights are reserved. You may view and print pages from this Website for personal, non-commercial use only, provided that all copyright notices remain intact. Reproduction, distribution, modification, or commercial use of any content without the prior written consent of TwentyOne06 is strictly prohibited."]},{"id":"use-of-website","title":"3. Use of This Website","paragraphs":["You agree to use this Website only for lawful purposes and in a manner that does not infringe the rights of any third party. You must not use this Website to transmit unsolicited commercial communications, introduce malicious software, attempt to gain unauthorised access to any part of the Website or its systems, copy or extract content without permission, or violate any applicable local, national, or international law or regulation."]},{"id":"enquiries","title":"4. Enquiries and Services","paragraphs":["Information about TwentyOne06''s services on this Website is provided for general information only and does not constitute a binding offer or contract. Submitting an enquiry through our contact form or by email does not create a contractual relationship between you and TwentyOne06. All project engagements are subject to a separate written agreement between TwentyOne06 and the client."]},{"id":"liability","title":"5. Disclaimers and Limitation of Liability","paragraphs":["The content on this Website is provided in good faith and for general information only. TwentyOne06 makes no warranties, express or implied, regarding the accuracy, completeness, or fitness for purpose of any information on this Website. To the fullest extent permitted by applicable UAE law, TWENTYONE ZERO SIX PROJECT MANAGEMENT shall not be liable for any loss or damage - whether direct, indirect, incidental, or consequential - arising from your use of or reliance on this Website or its content, or from your inability to access the Website. We do not warrant that the Website will be uninterrupted, error-free, or free from viruses or other harmful components."]},{"id":"third-party-links","title":"6. Third-Party Links","paragraphs":["This Website may contain links to third-party websites for your convenience. TwentyOne06 has no control over the content of those websites and accepts no responsibility for them or for any loss or damage that may arise from your use of them. The inclusion of any link does not imply endorsement by TwentyOne06."]},{"id":"privacy","title":"7. Privacy and Data Protection","paragraphs":["Your use of this Website is governed by our Privacy Policy, which is incorporated into these Terms by reference. Please review our Privacy Policy to understand how we collect, use, and protect your information."],"link":{"label":"Privacy Policy","to":"/privacy"}},{"id":"severability","title":"8. Severability","paragraphs":["If any provision of these Terms is found to be invalid, unlawful, or unenforceable, that provision shall be modified or removed to the minimum extent necessary. The remaining provisions shall continue in full force and effect."]},{"id":"governing-law","title":"9. Governing Law","paragraphs":["These Terms and Conditions shall be governed by and construed in accordance with the laws of the United Arab Emirates, as applied in the Emirate of Dubai. Any disputes shall be subject to the exclusive jurisdiction of the courts of Dubai, UAE."]},{"id":"changes","title":"10. Changes to These Terms","paragraphs":["TwentyOne06 reserves the right to revise these Terms at any time. The date of the most recent revision is shown at the top of this page. Your continued use of the Website following any changes constitutes your acceptance of the revised Terms."]},{"id":"contact","title":"11. Contact Us","paragraphs":["If you have any questions regarding these Terms and Conditions, please contact us:"],"showAddress":true}],"controller":{"name":"TWENTYONE ZERO SIX PROJECT MANAGEMENT (trading as ''TwentyOne06'')","lines":["Al Maktab, Office 304, 23rd Street","Al Barsha First, Al Barsha, Dubai","United Arab Emirates"],"phone":"+971 4 554 8082","phoneHref":"tel:+97145548082","email":"info@twentyone06.com","web":"www.twentyone06.com","webHref":"https://www.twentyone06.com"}}'::jsonb, true);
INSERT INTO public.marketing_pages (id, slug, title, content, published)
    VALUES ('85393031-20ba-428e-a3e8-c2846014cd80', 'about', 'About', '{"eyebrow":"The Studio","title":["A Practice Of","Quiet Luxury"],"description":"Twentyone06 is an interior design studio crafting timeless spaces with elegance, precision, and a deep respect for how people live.","body_html":"<p>We believe luxury is not excess - it is clarity. Every project begins with listening: to the site, to the client, and to the materials that will age with dignity.</p><p>Our team moves fluidly between concept, fabrication, and installation, working with trusted artisans so the finished interior feels inevitable rather than assembled.</p><p>From private residences to hospitality concepts, the through-line is the same: proportion, tactility, and atmospheres that hold their own over years.</p>","story":["We believe luxury is not excess - it is clarity. Every project begins with listening: to the site, to the client, and to the materials that will age with dignity.","Our team moves fluidly between concept, fabrication, and installation, working with trusted artisans so the finished interior feels inevitable rather than assembled.","From private residences to hospitality concepts, the through-line is the same: proportion, tactility, and atmospheres that hold their own over years."],"imageA":"https://images.pexels.com/photos/1080721/pexels-photo-1080721.jpeg?auto=compress&cs=tinysrgb&dpr=2&w=900","imageB":"https://images.pexels.com/photos/2724749/pexels-photo-2724749.jpeg?auto=compress&cs=tinysrgb&dpr=2&w=1000","cta":"Start a Conversation"}'::jsonb, true);
INSERT INTO public.marketing_pages (id, slug, title, content, published)
    VALUES ('3848784f-c907-44d9-a6ff-9bedd81c7c54', 'new-home', 'New Home', '{"hero":{"eyebrow":"Creative Design Studio","titleLines":[{"before":"Design by the ","accent":"People."},{"before":"For the ","accent":"People."}],"description":"Dubai''s multi-award winning interior design and branding studio.","sectors":"Hospitality  ·  F&B  ·  Hotels  ·  Retail  ·  Commercial","ctas":[{"label":"See Our Work","to":"/projects"},{"label":"Let''s Talk","to":"/contact"}],"image":"https://images.pexels.com/photos/3184291/pexels-photo-3184291.jpeg?auto=compress&cs=tinysrgb&dpr=2&w=1920","rail":[{"label":"Years of Craft","value":"10+"},{"label":"Projects Delivered","value":"50+"},{"label":"Clients Worldwide","value":"50K+"}]},"philosophy":{"eyebrow":"The Twentyone06 Philosophy","title":["We Design For","People."],"body":"Every space we design starts with a question: what does this need to do for the people using it? Not aesthetically. Commercially. Experientially. Operationally. In hospitality, F&B, and retail, the design is not decoration. It is the reason guests stay longer, come back, and bring others. We design with that understanding at the centre of every brief - bold where it counts, precise where it matters, and always in service of the people the space is built for.","cta":"More About Us","ctaTo":"/about","image":"https://images.pexels.com/photos/2379005/pexels-photo-2379005.jpeg?auto=compress&cs=tinysrgb&dpr=2&w=1200"},"services":{"eyebrow":"What We Do","title":"Services","cta":"View All Services","ctaTo":"/services","items":[{"index":"01","slug":"interior-design","title":"Interior Design","description":"Full-service interior design for hospitality, F&B, hotels, retail, and commercial spaces across the UAE and GCC.","detail":"TwentyOne06 is a full-service interior design studio in Dubai, specialising in hospitality, F&B, hotels, retail, and commercial spaces across the UAE and GCC. We cover the full arc of every project from spatial planning and concept design through to construction supervision and final handover, ensuring every detail of what was designed is precisely what gets built.","bullets":["Hospitality, F&B, and hotel interior design","Retail and commercial space design","Restaurant and bar design","Concept development and spatial planning","Construction documentation and on-site supervision"],"cta":"Let''s Design Your Space","image":"https://images.pexels.com/photos/1571468/pexels-photo-1571468.jpeg?auto=compress&cs=tinysrgb&dpr=2&w=900"},{"index":"02","slug":"branding","title":"Branding","description":"Visual identities, naming systems, and brand frameworks that give hospitality, F&B, and retail a clear voice beyond four walls.","detail":"A great interior without a coherent brand identity is a missed opportunity. TwentyOne06''s branding studio in Dubai creates visual identities, naming systems, and brand frameworks that reflect the spirit of a space, giving hospitality, F&B, and retail businesses across the UAE and GCC a clear, consistent voice beyond four walls.","bullets":["Brand identity, packaging and visual systems","Logo design and naming strategy","Signage and environmental graphics","Brand guidelines and asset libraries","Brand refresh and repositioning"],"cta":"Build Your Identity","image":"https://images.pexels.com/photos/3184291/pexels-photo-3184291.jpeg?auto=compress&cs=tinysrgb&dpr=2&w=900"},{"index":"03","slug":"design-management","title":"Design Management","description":"Expert design oversight, local market knowledge, and on-the-ground accountability from first decision to final sign-off.","detail":"TwentyOne06''s Design Management service provides expert design oversight, local market knowledge, and on-the-ground accountability. From the first design decision to the final quality sign-off across Dubai, the UAE, and the GCC.","bullets":["Material selection and specification - UAE and GCC market","Design coordination across all project stakeholders","On-site quality review and design sign-off","Value engineering that protects creative intent","Cost and programme alignment in real time"],"cta":"Let''s Manage Your Design","image":"https://images.pexels.com/photos/271624/pexels-photo-271624.jpeg?auto=compress&cs=tinysrgb&dpr=2&w=900"},{"index":"04","slug":"design-strategy","title":"Design Strategy And Operations","description":"Define what a space must achieve commercially, experientially, and operationally before a single line is drawn.","detail":"Before a single line is drawn, the most important decisions are already being made. TwentyOne06''s Design Strategy and Operations service helps hospitality and F&B operators across Dubai, Saudi Arabia, Kuwait, and the UAE, define what a space needs to achieve commercially, experientially, and operationally so the design that follows has a clear purpose and a measurable outcome.","bullets":["Pre-design strategic consultation","Space programming and commercial viability review","Guest experience mapping and journey design","Revenue-driving design frameworks","Post-occupancy review and optimisation"],"cta":"Plan With Us","image":"https://images.pexels.com/photos/1866149/pexels-photo-1866149.jpeg?auto=compress&cs=tinysrgb&dpr=2&w=900"}]},"projects":{"eyebrow":"Our Work","title":"Our Creations","cta":"Explore all projects","ctaTo":"/projects"},"clients":{"eyebrow":"Trusted by Visionaries"},"testimonials":[{"quote":"Twentyone06 turned our vision into a powerful reality - spaces that feel intentional, bold, and unmistakably ours.","name":"Studio Client","role":"Hospitality Founder","image":"https://images.pexels.com/photos/2379004/pexels-photo-2379004.jpeg?auto=compress&cs=tinysrgb&dpr=2&w=900"},{"quote":"They translated the way we live into a home that feels effortless, personal, and beautifully resolved.","name":"Amina Rahman","role":"Residential Client","image":"https://images.pexels.com/photos/1102341/pexels-photo-1102341.jpeg?auto=compress&cs=tinysrgb&dpr=2&w=900"},{"quote":"Every decision had purpose. The finished space gives our guests an experience they remember long after leaving.","name":"Omar El-Sayed","role":"Restaurant Founder","image":"https://images.pexels.com/photos/1043471/pexels-photo-1043471.jpeg?auto=compress&cs=tinysrgb&dpr=2&w=900"},{"quote":"The team balanced commercial demands with warmth and character. Our new space performs as strongly as it looks.","name":"Leila Haddad","role":"Property Developer","image":"https://images.pexels.com/photos/2379005/pexels-photo-2379005.jpeg?auto=compress&cs=tinysrgb&dpr=2&w=900"},{"quote":"Twentyone06 challenged the expected and delivered a confident identity that finally reflects who we are.","name":"Daniel Mercer","role":"Creative Director","image":"https://images.pexels.com/photos/2381069/pexels-photo-2381069.jpeg?auto=compress&cs=tinysrgb&dpr=2&w=900"}],"contact":{"ctaTitle":["Let’s Create Something","Extraordinary."],"ctaButton":"Start a Project","ctaTo":"/contact","formTitle":"Send a Message","submit":"Send Message","fields":[{"id":"name","label":"Name","type":"text","placeholder":"Your name","required":true},{"id":"email","label":"Email","type":"email","placeholder":"you@example.com","required":true},{"id":"interest","label":"Project Type","type":"select","placeholder":"Select a focus","required":true,"options":["Interior Design","Branding","Design Management","Design Strategy And Operations"]},{"id":"message","label":"Message","type":"textarea","placeholder":"Tell us about your project…","required":true}],"details":[{"label":"Email","value":"info@twentyone06.com","href":"mailto:info@twentyone06.com"},{"label":"Phone","value":"04 554 8082","href":"tel:+97145548082"},{"label":"Studio","value":"Al Maktab - Office 304, 23rd St, Al Barsha First, Al Barsha, Dubai"}],"social":[{"label":"Facebook","href":"https://www.facebook.com/p/TwentyOne06-100054351738420/"},{"label":"Instagram","href":"https://www.instagram.com/twentyone06/"},{"label":"Linkedin","href":"https://www.linkedin.com/company/twentyone06"}],"copyright":"© 2026 TwentyOne06. All rights reserved."}}'::jsonb, true);
INSERT INTO public.marketing_pages (id, slug, title, content, published)
    VALUES ('b577ad3b-5c8f-4606-af0b-fbb11fab6f93', 'contact', 'Contact', '{"eyebrow":"Get in Touch","title":["Let’s Begin Your","Design Journey"],"description":"Share a few details about your project. Our studio will respond within two business days to arrange a private consultation.","image":"https://images.pexels.com/photos/1571460/pexels-photo-1571460.jpeg?auto=compress&cs=tinysrgb&dpr=2&w=1400","details":[{"label":"Visit","lines":["Al Maktab - Office 304","23rd St, Al Barsha First","Al Barsha, Dubai"]},{"label":"Call","lines":["04 554 8082"],"href":"tel:+97145548082"},{"label":"Email","lines":["info@twentyone06.com"],"href":"mailto:info@twentyone06.com"},{"label":"Studio Hours","lines":["Mon - Fri · 9:00 - 18:00","Sat by appointment"]}],"form":{"fields":[{"id":"name","label":"Full Name","type":"text","placeholder":"Your name","required":true},{"id":"email","label":"Email","type":"email","placeholder":"you@example.com","required":true},{"id":"phone","label":"Phone","type":"tel","placeholder":"+1 000 000 0000","required":false},{"id":"interest","label":"Project Interest","type":"select","placeholder":"Select a focus","required":true,"options":["Interior Design","Branding","Design Management","Design Strategy And Operations","Private Tour / Consultation"]},{"id":"message","label":"Tell Us About Your Space","type":"textarea","placeholder":"Location, timeline, and what you hope to achieve…","required":true}],"submit":"Send Message","note":"By submitting, you agree to be contacted by Twentyone06 regarding your inquiry. We never share your details."}}'::jsonb, true);